from matplotlib.patches import FancyBboxPatch
import base64
from io import BytesIO
from datetime import datetime
import json

# ── Load & prep data ──────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'])
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Month'] = df['Date'].dt.month
df['Decade'] = (df['Year'] // 10) * 10

prices = df['Crude_Oil_Price']

first_date = df['Date'].iloc[0]
last_date = df['Date'].iloc[-1]
first_price = prices.iloc[0]
last_price = prices.iloc[-1]
n_months = len(df)
n_years = (last_date - first_date).days / 365.25

# ── KPI Calculations ──────────────────────────────────────────────
price_min = prices.min()
price_max = prices.max()
price_range = price_max - price_min
price_mean = prices.mean()
price_median = prices.median()
price_std = prices.std()
cagr = (last_price / first_price) ** (1 / n_years) - 1

# Month-over-month changes
df['MoM_Abs'] = prices.diff().abs()
df['MoM_Pct'] = prices.pct_change() * 100
max_mom_abs = df['MoM_Abs'].max()
max_mom_idx = df['MoM_Abs'].idxmax()
max_mom_pct = df['MoM_Pct'].max()
max_mom_pct_idx = df['MoM_Pct'].idxmax()
max_mom_neg_pct = df['MoM_Pct'].min()
max_mom_neg_pct_idx = df['MoM_Pct'].idxmin()

# Year-over-year changes
df['YoY_Pct'] = prices.pct_change(12) * 100
max_yoy_pct = df['YoY_Pct'].max()
max_yoy_pct_idx = df['YoY_Pct'].idxmax()
max_yoy_neg_pct = df['YoY_Pct'].min()
max_yoy_neg_pct_idx = df['YoY_Pct'].idxmin()

# Decade analysis
decade_stats = df.groupby('Decade').agg(
    Avg_Price=('Crude_Oil_Price', 'mean'),
    Median_Price=('Crude_Oil_Price', 'median'),
    Std_Dev=('Crude_Oil_Price', 'std'),
    Min_Price=('Crude_Oil_Price', 'min'),
    Max_Price=('Crude_Oil_Price', 'max'),
    Months=('Crude_Oil_Price', 'count')
).round(2)

decade_highest_avg = decade_stats['Avg_Price'].idxmax()
decade_highest_std = decade_stats['Std_Dev'].idxmax()

# Percentiles
p5 = np.percentile(prices.dropna(), 5)
p25 = np.percentile(prices.dropna(), 25)
p75 = np.percentile(prices.dropna(), 75)
p95 = np.percentile(prices.dropna(), 95)

