  </p>

  <table class="table-numeric">
    <thead>
      <tr>
        <th>Decade</th>
        <th>Avg Price ($)</th>
        <th>Median Price ($)</th>
        <th>Std Dev ($)</th>
        <th>Minimum ($)</th>
        <th>Maximum ($)</th>
      </tr>
    </thead>
    <tbody>
'''
for row in decade_table_rows:
    html += f'      <tr><td>{row[0]}</td><td>{row[1]}</td><td>{row[2]}</td><td>{row[3]}</td><td>{row[4]}</td><td>{row[5]}</td></tr>\n'

html += f'''
    </tbody>
  </table>

  <div class="chart-container">
    <img src="{chart_decade_bar}" alt="Average Price by Decade">
    <div class="chart-caption">Figure 4: Average monthly crude oil price for each decade.</div>
  </div>

  <div class="chart-container">
    <img src="{chart_decade_box}" alt="Price Distribution by Decade">
    <div class="chart-caption">Figure 5: Box-and-whisker plot showing the distribution of monthly prices within each decade.</div>
  </div>

  <h3>Decade Narratives</h3>
'''

# Build decade narratives from data
decade_narratives = {
