for yr, row_data in recent_yearly.iterrows():
    html += f'      <tr><td>{int(yr)}</td><td>${row_data["mean"]:.2f}</td><td>${row_data["min"]:.2f}</td><td>${row_data["max"]:.2f}</td></tr>\n'

html += f'''
    </tbody>
  </table>

  <h3>Key Conclusions</h3>
  <ol>
    <li>
      <strong>Structural regime changes dominate the narrative.</strong> Crude oil prices are not well-described by
